package server

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"strings"
	"time"

	"github.com/PeiceOfToast/shrinkyourshit/internal/store"
)

// Pairing (task 08). A node joins either with a one-time token (approved
// immediately) or without one (pending until the admin approves). Keys are
// generated by the server: the token path returns the key in the pair
// response, the approval path keeps the raw key in the node's key_once
// column until the node retrieves it once through GET /pair/{id}.

// PairingTokenTTL is how long a pairing token stays valid (task 08: 24h,
// single use).
const PairingTokenTTL = 24 * time.Hour

// Pairing state errors the API maps to HTTP statuses.
var (
	// ErrInvalidToken: unknown, expired or already-used token → 401.
	ErrInvalidToken = errors.New("node: pairing token invalid, expired or already used")
	// ErrPairInput: bad request body (missing name, bad access mode or
	// mappings) → 400.
	ErrPairInput = errors.New("node: invalid pairing request")
	// ErrNotPending: approve on a node that is not pending → 409.
	ErrNotPending = errors.New("node: node is not pending approval")
)

// PairInput is the POST /pair body (API.md, task 08). Capabilities is the
// raw JSON object; it is stored verbatim (the first heartbeat refreshes it).
type PairInput struct {
	Token        string
	Name         string
	OS           string
	Arch         string
	Capabilities string
}

// Pair joins a node. With a valid token the node is created approved and
// the raw key is returned. Without (or with an empty) token the node is
// created pending and no key exists yet. An invalid non-empty token is
// ErrInvalidToken (→ 401): a wrong token must not silently downgrade to a
// pending request.
func (r *NodeRegistry) Pair(ctx context.Context, in PairInput) (*store.Node, string, error) {
	name := strings.TrimSpace(in.Name)
	if name == "" {
		return nil, "", fmt.Errorf("%w: name is required", ErrPairInput)
	}
	caps := strings.TrimSpace(in.Capabilities)
	if caps == "" {
		caps = "{}"
	}

	token := strings.TrimSpace(in.Token)
	if token != "" {
		t, err := r.st.GetPairingTokenByHash(ctx, HashToken(token))
		if errors.Is(err, store.ErrNotFound) {
			return nil, "", ErrInvalidToken
		}
		if err != nil {
			return nil, "", fmt.Errorf("node: token lookup: %w", err)
		}
		now := time.Now().UTC()
		if !t.UsedAt.IsZero() || !t.ExpiresAt.After(now) {
			return nil, "", ErrInvalidToken
		}

		key, err := generateNodeKey()
		if err != nil {
			return nil, "", err
		}
		node := &store.Node{
			Name:         name,
			KeyHash:      HashKey(key),
			OS:           in.OS,
			Arch:         in.Arch,
			Capabilities: caps,
			AccessMode:   store.NodeAccessAuto,
			PathMappings: "[]",
			Status:       store.NodeStatusApproved,
			Enabled:      true,
		}
		if err := r.st.CreateNode(ctx, node); err != nil {
			return nil, "", fmt.Errorf("node: create paired: %w", err)
		}
		t.UsedAt = now
		if err := r.st.UpdatePairingToken(ctx, t); err != nil {
			return nil, "", fmt.Errorf("node: consume token: %w", err)
		}
		r.log.Info("node paired with token", "node", node.ID, "name", node.Name)
		r.publish(EventNodeUpdated, NewNodeDTO(node))
		return node, key, nil
	}

	// No token: the node waits for admin approval. The key is generated
	// at approval time and delivered once through GET /pair/{id}.
	node := &store.Node{
		Name:         name,
		OS:           in.OS,
		Arch:         in.Arch,
		Capabilities: caps,
		AccessMode:   store.NodeAccessAuto,
		PathMappings: "[]",
		Status:       store.NodeStatusPending,
		Enabled:      true,
	}
	if err := r.st.CreateNode(ctx, node); err != nil {
		return nil, "", fmt.Errorf("node: create pending: %w", err)
	}
	r.log.Info("node asks to join", "node", node.ID, "name", node.Name)
	r.publish(EventNodeUpdated, NewNodeDTO(node))
	return node, "", nil
}

// CreateToken mints a one-time pairing token. Only the hash is stored; the
// raw token exists in this return value and in the install commands the
// admin copies.
func (r *NodeRegistry) CreateToken(ctx context.Context) (raw string, expiresAt time.Time, err error) {
	raw, err = generateNodeKey()
	if err != nil {
		return "", time.Time{}, err
	}
	expiresAt = time.Now().UTC().Add(PairingTokenTTL)
	t := &store.PairingToken{TokenHash: HashToken(raw), ExpiresAt: expiresAt}
	if err := r.st.CreatePairingToken(ctx, t); err != nil {
		return "", time.Time{}, fmt.Errorf("node: create token: %w", err)
	}
	return raw, expiresAt, nil
}

// PollPair answers GET /pair/{id}. A pending node stays pending; an
// approved node gets its raw key exactly once (the stored copy is wiped on
// retrieval, afterwards only the hash remains); a revoked node reports
// revoked so the worker stops polling. Unknown ids are store.ErrNotFound.
func (r *NodeRegistry) PollPair(ctx context.Context, nodeID string) (*store.Node, string, error) {
	node, err := r.st.GetNode(ctx, nodeID)
	if err != nil {
		return nil, "", err
	}
	if node.Status != store.NodeStatusApproved || node.KeyOnce == "" {
		return node, "", nil
	}
	key, err := r.st.ConsumeNodeKeyOnce(ctx, node.ID)
	if err != nil {
		return nil, "", fmt.Errorf("node: consume key: %w", err)
	}
	if key != "" {
		r.log.Info("node retrieved its key", "node", node.ID)
	}
	return node, key, nil
}

// Approve turns a pending node into an approved one and generates its
// key (delivered once through PollPair). Already-approved or revoked
// nodes are ErrNotPending (→ 409).
func (r *NodeRegistry) Approve(ctx context.Context, id string) (*store.Node, error) {
	node, err := r.st.GetNode(ctx, id)
	if err != nil {
		return nil, err
	}
	if node.Status != store.NodeStatusPending {
		return nil, ErrNotPending
	}
	key, err := generateNodeKey()
	if err != nil {
		return nil, err
	}
	node.Status = store.NodeStatusApproved
	node.Enabled = true
	node.KeyHash = HashKey(key)
	node.KeyOnce = key
	if err := r.st.UpdateNode(ctx, node); err != nil {
		return nil, fmt.Errorf("node: approve: %w", err)
	}
	r.log.Info("node approved", "node", node.ID, "name", node.Name)
	r.publish(EventNodeUpdated, NewNodeDTO(node))
	return node, nil
}

// Revoke disables a node: its key hash and one-time key are deleted (the
// next worker request authenticates as nothing) and its claimed/running
// jobs return to the queue. Idempotent on an already-revoked node.
func (r *NodeRegistry) Revoke(ctx context.Context, id string) (*store.Node, error) {
	node, err := r.st.GetNode(ctx, id)
	if err != nil {
		return nil, err
	}
	node.Status = store.NodeStatusRevoked
	node.KeyHash = ""
	node.KeyOnce = ""
	if err := r.st.UpdateNode(ctx, node); err != nil {
		return nil, fmt.Errorf("node: revoke: %w", err)
	}
	r.requeueInFlight(ctx, node.ID)
	r.log.Info("node revoked", "node", node.ID, "name", node.Name)
	r.publish(EventNodeUpdated, NewNodeDTO(node))
	return node, nil
}

// Delete removes a node row entirely (the Reject action for a pending
// node, and cleanup for revoked ones). Its in-flight jobs are requeued
// first so nothing is stranded on a node that no longer exists.
func (r *NodeRegistry) Delete(ctx context.Context, id string) error {
	node, err := r.st.GetNode(ctx, id)
	if err != nil {
		return err
	}
	r.requeueInFlight(ctx, node.ID)
	if err := r.st.DeleteNode(ctx, node.ID); err != nil {
		return fmt.Errorf("node: delete: %w", err)
	}
	r.log.Info("node deleted", "node", node.ID, "name", node.Name)
	r.publish(EventNodeUpdated, NewNodeDTO(node))
	return nil
}

// NodeUpdateParams is the PUT /nodes/{id} body. Pointers distinguish "not
// sent" from a zero value (API.md).
type NodeUpdateParams struct {
	Name            *string
	Enabled         *bool
	AccessMode      *string
	PathMappings    *string // raw JSON, validated by ValidatePathMappings
	ThroughputLimit *int64  // MB/s, 0 = unlimited (task 09)
}

// Update applies a partial node update. Unknown access modes, broken
// path mappings and negative throughput limits are ErrPairInput (→ 400).
func (r *NodeRegistry) Update(ctx context.Context, id string, p NodeUpdateParams) (*store.Node, error) {
	node, err := r.st.GetNode(ctx, id)
	if err != nil {
		return nil, err
	}
	if p.Name != nil {
		name := strings.TrimSpace(*p.Name)
		if name == "" {
			return nil, fmt.Errorf("%w: name cannot be empty", ErrPairInput)
		}
		node.Name = name
	}
	if p.Enabled != nil {
		node.Enabled = *p.Enabled
	}
	if p.AccessMode != nil {
		mode := strings.TrimSpace(*p.AccessMode)
		if !validNodeAccessMode(mode) {
			return nil, fmt.Errorf("%w: access_mode must be one of %s",
				ErrPairInput, strings.Join(store.NodeAccessModeValues(), ", "))
		}
		node.AccessMode = mode
	}
	if p.PathMappings != nil {
		if err := ValidatePathMappings(*p.PathMappings); err != nil {
			return nil, err
		}
		node.PathMappings = *p.PathMappings
	}
	if p.ThroughputLimit != nil {
		if *p.ThroughputLimit < 0 {
			return nil, fmt.Errorf("%w: throughput_limit_mbps cannot be negative", ErrPairInput)
		}
		node.ThroughputLimit = *p.ThroughputLimit
	}
	if err := r.st.UpdateNode(ctx, node); err != nil {
		return nil, fmt.Errorf("node: update: %w", err)
	}
	r.publish(EventNodeUpdated, NewNodeDTO(node))
	return node, nil
}

// requeueInFlight hands the node's claimed/running jobs back to the queue.
func (r *NodeRegistry) requeueInFlight(ctx context.Context, nodeID string) {
	if r.queue == nil {
		return
	}
	if _, err := r.queue.RequeueNodeJobs(ctx, nodeID); err != nil {
		r.log.Error("node: requeue in-flight jobs", "node", nodeID, "err", err)
	}
}

// validNodeAccessMode checks against the ARCHITECTURE.md enum.
func validNodeAccessMode(v string) bool {
	for _, ok := range store.NodeAccessModeValues() {
		if v == ok {
			return true
		}
	}
	return false
}

// ValidatePathMappings checks the raw path_mappings JSON of a node: an
// array of {server_path, node_path} objects, both non-empty. An empty or
// missing value is valid (identity mapping).
func ValidatePathMappings(raw string) error {
	if strings.TrimSpace(raw) == "" {
		return nil
	}
	var mappings []PathMapping
	if err := json.Unmarshal([]byte(raw), &mappings); err != nil {
		return fmt.Errorf("%w: path_mappings must be a JSON array of {server_path, node_path}", ErrPairInput)
	}
	for _, m := range mappings {
		if strings.TrimSpace(m.ServerPath) == "" || strings.TrimSpace(m.NodePath) == "" {
			return fmt.Errorf("%w: every path mapping needs a server_path and a node_path", ErrPairInput)
		}
	}
	return nil
}
